import ch01_complete
from author import *
def E(n):return f'EN01-H000-H030-P{n:03d}'
def refs(*n):return ' '.join(E(i) for i in n)
N('从演化角度，细菌、古菌和真核细胞在膜区室、遗传表达、骨架分裂及亲缘证据上怎样比较？',[
P('三者共享遗传与代谢基础；细菌、古菌无真核式核膜，真核以核及内膜建立区室。细菌与古菌质膜承担多功能代谢，典型真核把许多过程分配给不同器官；古菌膜脂的醚键和部分跨膜四醚结构又区别于典型酯键脂。','共同基础、有无典型核膜、区室分工与膜脂三组对比。','2.11 2.82 2.115 2.120 2.157','三类演化比较的共同基础;三类膜区室与功能分工;古菌膜脂化学差异'),
P('细菌转录翻译可耦联；古菌操纵子等组织近似细菌，组蛋白、RNA聚合酶及起始Met等表达装置又更近真核；真核的核区室和染色质支持多层表达控制。真核骨架与有丝分裂装置组织复杂DNA的分配，但细菌也有受调控的分裂蛋白，不能套用旧表“完全无骨架”的绝对结论。','细菌耦联；古菌两组表达特征；真核表达分配与严格范围。','2.58 2.61 2.84 2.121 2.157','演化比较的细菌信息耦联;古菌细菌式基因组织和真核式表达;真核表达与染色质分配的复杂化'),
P('直系同源基因和rRNA等序列比较显示古菌、真核的表达相关亲缘，而非仅按外观把古菌与细菌并为完全同一类。演化比较要区分共有基础、分支特征与后续复杂化，不把现存某类解释为另一类尚未变化的祖先。','同源序列证据与形态比较的区别；共有基础与派生特征的逻辑。','2.75 2.86 2.157','三域关系的分子证据;共有与分支特征的演化解释')],kind='整合比较')
N('如何从细胞与遗传角度区分生命复制与晶体生长、燃烧或水波形成？自由能输入在其中起什么作用？',[
P('细胞是膜包围、含浓集水溶液的化学系统，可以生长并复制，生物从环境获得物质形成自身及后代。生命复制向后代传递确定种类特征的遗传信息；晶体、火焰与水波也可出现增长或结构，但没有同类的亲子特征信息传递。','膜和水溶化学体系；生长复制；遗传连续性与三类非生命例子区别。',refs(3,4,16),'细胞膜包围的浓缩水溶体系;物质摄取与自复制;遗传区分生命与晶体火焰水波'),
P('火焰同样消耗自由能，所以能量消耗本身不是充分判据；细胞用自由能驱动按遗传信息组织和维持复杂化学反应体系。生命共性与种类、形态多样性并存，细胞结构、功能、行为研究是解释这二者的重要基础。','自由能不是单独判据；遗传信息指导复杂体系及同一性多样性。',refs(5,6,16),'自由能消耗不是生命充分条件;能量与遗传信息共同组织生命体系;多样性与基本机制恒定并存')],kind='概念辨析')
N('图1-1的海胆、小鼠和墨角藻卵如何说明单细胞遗传信息决定发育的物种特征？请同时读出三个卵图比例尺。（需看图：A/C/E卵与B/D/F个体对应）',[
P('A/B对应海胆（sea urchin），C/D对应小鼠（mouse），E/F对应墨角藻（Fucus）。外表相近的起始细胞形成不同物种，说明不能用卵外形相似推断遗传指令相同；多细胞个体经细胞分裂从单细胞形成，起始细胞须携带构建物种的遗传信息和复制所需装置。','三组对象配对；外形近似与遗传信息不同；单细胞起源和复制装置。',refs(17,20,21,22,23,24,25,29),'海胆卵到海胆对应;小鼠卵到小鼠对应;墨角藻卵到墨角藻对应;卵形相似不等于遗传指令相同;多细胞个体来自单细胞分裂'),
P('A图标尺100 μm，C与E均50 μm。成年海胆、小鼠、藻体照片没有共同尺度，不能以照片框大小比较成年个体真实大小。','100、50、50μm对应正确；成年照片无共同尺度。',refs(20,21,22,29),'海胆卵100μm标尺;小鼠卵50μm标尺;墨角藻卵50μm标尺;成年照片尺度不统一')],images=[('ENFIG0006','front','Figure 1-1A'),('ENFIG0009','front','Figure 1-1B'),('ENFIG0007','front','Figure 1-1C'),('ENFIG0010','front','Figure 1-1D'),('ENFIG0008','front','Figure 1-1E'),('ENFIG0011','front','Figure 1-1F')],kind='图像与遗传')
N('基因组是什么？跨物种读取DNA的能力为何支持共同祖先观点，英文教材估计该祖先存在于何时？',[
P('基因组（genome）是DNA线性核苷酸序列中承载的全套遗传信息。DNA为长而不分支的双链聚合物，统一使用A、T、C、G四种核苷酸次序记录信息；人和细菌DNA经必要适配可被另一种细胞的装置读取、解释、复制。','基因组定义、DNA结构与四字母信息；跨物种读取的必要适配。',refs(19,30),'基因组全套DNA序列遗传信息;DNA长不分支双链及ATCG;跨物种读取解释复制及适配条件'),
P('共享信息记录与执行形式，提供普遍共同祖先证据。英文教材估计细胞演化已超过35亿年，共同祖先约在35—38亿年前；快速测序使数万物种的全基因组可比较。这些是本版估计与技术状态。','相同语言与共同祖先的推理；35—38亿年、数万基因组及估计属性。',refs(19,30),'共同遗传语言支持共同祖先;共同祖先35—38亿年估计;快速测序与数万完整基因组')],kind='概念与证据')
N('英文教材怎样用计算机类比遗传信息？数据载体变化与生命共同DNA载体形成什么对照？',[
P('教材举约10⁶ bytes可记录数百页文字或一幅图片、约10⁹ bytes可记录60分钟网络视频，说明信息可按量度且可有不同物理载体。旧磁盘和磁带约25年后可能不能由新机器读取；相比之下，生命数十亿年仍共享DNA信息体系，这种高度保守性支持共同起源。','两组数量例子、60分钟与载体淘汰；生命语言保守的对照及证据意义。',refs(19),'教材10⁶bytes文字图片类比;10⁹bytes60分钟视频类比;旧磁盘磁带与25年例子;载体可变和生命DNA保守的对照')],detail='上述字节值是教材教学类比，受编码、分辨率和压缩条件影响，不作为所有文件格式的精确换算。',kind='数量与类比')
N('读图1-2：DNA核苷酸怎样形成有极性的骨架，互补碱基怎样指导新链？区分共价键、氢键与双螺旋。（需看图：A—E构件、链方向、互补配对与键型）',[
P('核苷酸（nucleotide）由脱氧核糖、磷酸与含氮碱基组成；四种碱基为A腺嘌呤、G鸟嘌呤、C胞嘧啶、T胸腺嘧啶。图注以约35个共价连接原子描述单元，实际随种类而变。糖—磷酸连接成重复骨架，碱基侧向伸出；非对称单元赋予链方向性。','三个组成、四碱基与约数；骨架连接、伸出碱基及非对称极性。',refs(32,33,34),'脱氧核苷酸糖磷酸碱基组成;A腺嘌呤G鸟嘌呤C胞嘧啶T胸腺嘧啶;图注约35原子的概括;糖磷酸骨架与碱基伸出;骨架非对称与方向性'),
P('预存链作模板，A与T、C与G匹配，使合适单体被保留并加入新链；新旧序列互补、骨架方向相反。如图原链GTAA…，互补链按对齐方向为…TTAC。链内骨架由强共价键维持，跨链碱基主要以较弱氢键配对；两条链缠绕为双螺旋，可容纳不同序列而保留基本形态。','模板选择、两组互补、反向骨架与序列示例；链内共价／链间氢键、双螺旋。',refs(32,34),'模板配对选择新单体;ATCG互补关系;新旧链反平行及序列示例;链内共价与链间氢键;双螺旋容纳不同序列')],images=[('ENFIG0012','front','Figure 1-2A—E；图未明确标出5′/3′编号，不凭图中左右方向编造链端标号。')],kind='分子结构读图')
N('DNA两条链为何可分离而骨架保持完整？每条模板怎样产生两个与亲代序列相同的DNA分子？（需看图：红色亲代链和黄色新链的分配）',[
P('链间碱基配对的氢键较链内糖—磷酸共价连接弱，两链可分开而不必切断骨架。每条旧链分别作为模板，以互补配对选择新核苷酸并聚合，形成两份子代双链，每份都有一条亲代链和一条新链。正确复制的子代序列与亲代相同。','弱氢键与强骨架；双模板、互补聚合、一旧一新和两份相同序列。',refs(35,36,37),'链间分开不切骨架的键强度原因;每条旧链分别为模板;互补聚合产生两份双链;每份亲代链与新链'),
P('不同细胞的复制速率、启停控制和辅助因子会不同，共通的是以DNA存信息、以模板聚合复制。图1-3颜色区分旧新，不表示DNA在现实中天然呈红黄两色。','共同机制与不同速度控制；颜色为图示编码。',refs(35,37),'复制速度启停辅助因子差异;模板聚合的普遍基础;图色编码旧新链')],images=[('ENFIG0013','front','Figure 1-3，红色为亲代骨架、黄色为新链骨架。')],kind='复制机制')
N('DNA复制、转录和翻译各使用什么模板、单体与产物？从DNA到蛋白质的表达为何需要两步？（需看图：图1-4三条反应箭头）',[
P('复制（replication）用DNA模板合成DNA；转录（transcription）用一段DNA合成RNA；翻译（translation）用mRNA信息决定氨基酸次序并合成蛋白质。前两者是核苷酸的模板聚合，翻译把核苷酸信息转为另一类聚合物氨基酸链，所以不能把翻译说成合成RNA。','模板、单体、产物三组配对；核苷酸到氨基酸的信息类别转变。',refs(39,42,43),'DNA复制模板产物;转录DNA到RNA;翻译RNA信息到氨基酸蛋白;核苷酸聚合与翻译化学类别区别')],images=[('ENFIG0014','front','Figure 1-4；箭头是本图表达主线，不表示所有RNA都被翻译或概括所有病毒信息流。')],kind='信息过程比较')
N('RNA与DNA的化学组成怎样区别？转录中的配对怎样把DNA信息改写为RNA序列？',[
P('RNA用核糖而DNA用脱氧核糖；RNA的U尿嘧啶替代DNA的T胸腺嘧啶，A、C、G相同。RNA的A、U、C、G分别与DNA模板的T、A、G、C配对，模板选择单体并指导聚合，形成代表该段遗传信息的单链RNA。','糖和U／T差异；四组模板配对；单链转录产物和信息对应。',refs(40),'RNA核糖DNA脱氧核糖;RNAU替代DNAT;RNA与DNA模板四组互补;单链RNA保留模板遗传信息')],kind='化学与机制')
N('为什么同一DNA片段可产生许多RNA，而RNA不都承担相同功能？',[
P('DNA片段可重复用于转录，产生许多相同RNA。DNA作为长期信息档案，RNA转录本则可大量产生并更新；许多mRNA将信息交给蛋白合成装置，另有RNA直接承担结构、催化或调控等任务。因此RNA不是全都要翻译的临时蛋白模板。','重复模板和大量转录本；档案与可更新副本；mRNA及直接功能RNA。',refs(41,57),'同段DNA可重复转录;DNA档案与RNA可更新副本;mRNA信息中介;非翻译RNA直接功能')],kind='机制与辨析')
N('蛋白质的单体、序列和折叠怎样相连？其质量比例、结构功能与催化作用应如何概括？',[
P('蛋白质（protein）为无分支的氨基酸聚合链，经典20种氨基酸以共享骨架共价连接，各自侧链赋予不同化学性质。氨基酸序列影响折叠及三维结构，进而决定特异结合和功能；序列经过演化选择，不是仅有长度才决定结构。忽略水后，蛋白质通常构成细胞质量的主要部分。','20种经典单体、共同核心与侧链、序列→折叠→特异功能；去水质量语境。',refs(45,46,47),'蛋白无分支氨基酸聚合链;经典20种与侧链差异;序列折叠三维特异功能;蛋白去水后质量主要部分'),
P('蛋白可形成和维持胞内外结构、产生运动、感受信号；许多蛋白的活性位点催化特定共价键形成或断裂，称酶（enzyme）。催化剂（catalyst）加快特定反应而在反应总体前后不被净消耗，不能把“加快任何变化”作为化学定义。','结构运动感信号、活性位点与特定反应；催化剂不净消耗。',refs(47,48),'蛋白结构运动感知功能;酶活性位点与特定反应;催化剂化学定义与日常含义区别')],kind='结构功能')
N('图1-5为什么把细胞看成自催化、可自复制体系？绿色和红色箭头分别表示什么，能否说所有催化剂都是蛋白质？（需看图：营养／废物和信息—催化反馈）',[
P('图A中细胞从食物获得构件和能量，催化剂集合加工这些资源，在分裂前复制整个体系并排废物。图B绿色箭头是DNA、RNA序列信息，指导核酸复制与蛋白序列；红色箭头为蛋白提供催化活性，支持DNA、RNA、蛋白生成。信息制造催化装置，催化装置又维持信息及自身生产，形成相互依赖反馈。','食物到构件能量、排废；绿色序列与红色催化；两者闭合反馈及复制。',refs(48,51,52,53),'食物构件能量及废物排出;分裂前复制催化集合;绿色信息箭头;红色催化箭头;信息与催化相互维持自复制'),
P('大多数催化剂为蛋白酶，但有些RNA也能催化，称核酶（ribozyme）。所以蛋白承担主要执行功能不等于RNA只能传递信息，也不等于全部催化剂均为蛋白。','大多数蛋白酶与少数催化RNA；RNA功能例外不可漏。',refs(51),'核酶为催化RNA;主要蛋白催化不等于全部')],images=[('ENFIG0015','front','Figure 1-5A'),('ENFIG0016','front','Figure 1-5B，绿色信息与红色催化箭头。')],kind='反馈整合')
N('四种核苷酸怎样编码20种经典氨基酸？请解释三联体数量、简并性、tRNA识别与核糖体作用。',[
P('mRNA按三核苷酸一组读取，称密码子（codon）；四种核苷酸可形成4³=64种三联体。编码关系允许多个密码子对应同一氨基酸，形成简并性；英文开篇将每个密码子都概括为编码氨基酸的措辞未区分终止信号，不能据此断言64个都编码氨基酸。','三联体和4³=64；多密码子同一氨基酸；不能把总三联体数等同氨基酸编码数。',refs(54,55),'三联体密码子;四种核苷酸形成64三联体;多个密码子同一氨基酸简并'),
P('tRNA（transfer RNA，转运核糖核酸）一端携带特定氨基酸，另一处反密码子（anticodon）通过配对识别某密码子或一组密码子；核糖体由rRNA和蛋白组成，使这套识别把mRNA次序转为氨基酸次序。翻译规则高度保守但有少量例外，教材把其部分任意性联系到早期偶然事件被遗传固定的假说。','tRNA氨基酸端与反密码子、配对识别；核糖体组成与信息转换；保守例外及冻结偶然的假说身份。',refs(54,55),'tRNA氨基酸与反密码子两端功能;识别一个或一组密码子;核糖体RNA蛋白与翻译;遗传码保守和例外;翻译任意性与冻结偶然假说')],kind='编码机制')
gap(E(55),'“每个密码子都指定一个氨基酸”的概括','开篇段未区分终止密码子；须与指定教材详细翻译章节核对，当前不导出64个都编码氨基酸的断言。')
N('英文教材怎样定义基因？为什么非蛋白编码片段也可属于基因，单个基因也不一定只产生一种蛋白形式？',[
P('基因（gene）为对应一个蛋白或一组紧密相关替代蛋白形式，或对应一个具有催化、调控、结构功能RNA的DNA序列片段。大DNA以特定边界序列区分不同表达单位，片段可转录为独立RNA；能产生功能性非翻译RNA的片段也是基因，而非只有蛋白编码部分才算基因。','DNA片段定义；蛋白替代形式、三类功能RNA；边界与非编码RNA基因。',refs(57),'基因为相应功能产物DNA片段;同基因可有相关替代蛋白形式;催化调控结构RNA基因;特定边界与表达单位;非翻译RNA片段也属基因')],kind='概念辨析')
N('细胞为什么不持续最大速率表达全部基因？调控DNA怎样影响蛋白质产生的时间和位置？',[
P('细胞按需求分别调整不同基因转录及翻译速率。编码片段间可分布调控DNA，结合特定调控蛋白以控制转录；不同类群调控DNA组织差异大，但调节策略具有共同基础。因此基因组不仅规定蛋白类别，还影响何时、何处及多少表达，不能只把基因看作固定产物名称表。','按需求独立调整、转录翻译；非编码调控DNA结合蛋白；类群差异、时间位置和水平。',refs(58),'按需求调节转录翻译;调控DNA与蛋白结合控制转录;调控DNA组织类群差异;基因组规定产物及时间位置')],kind='调控机制')
N('细胞为什么要不断输入自由能？用DNA复制解释自由能、热运动和秩序建立之间的联系。',[
P('细胞为远离化学平衡的动态体系。生长与复制须从环境输入自由能（free energy）及原料以驱动合成并保持组织；供应缺失时趋向平衡、结构衰败。模板复制要从随机运动的单体群中选择、按次序连接核苷酸，形成能抵抗扰动的稳定连接，这种有序构建需要自由能。','非平衡、环境自由能原料与维持；随机单体到模板排序和稳定连接的能量要求。',refs(60,61,62),'细胞远离化学平衡;自由能原料维持生长复制;能源缺失趋平衡衰败;模板排列连接对抗热扰动需能量'),
P('教材用蓄能弹簧陷阱类比：合适伙伴结合时进入较稳定、较低自由能状态，能量部分以热散失；这不意味着所有细胞反应就是该简单模型。动物主要从食物化学键获得所需能量，光合生物从阳光获得能量，并经反应网络转成细胞可用形式。','类比的结合降自由能及散热；能量来源对象与模型限制。',refs(61,62),'弹簧陷阱低自由能结合类比;释放自由能与散热;动物食物与光合阳光来源')],kind='因果解释')
N('细胞作为生化工厂共享哪些小分子基础？ATP的能量作用与不同营养方式怎样联系？',[
P('合成DNA、RNA和蛋白需处理糖、核苷酸、氨基酸等含碳小分子。ATP（adenosine triphosphate，三磷酸腺苷）是核苷酸类分子，也是驱动大量化学反应的自由能载体；不能只记缩写而遗漏能量耦联功能。','三类小分子、含碳基础及ATP核苷酸／自由能载体功能。',refs(64),'共享糖核苷酸氨基酸小分子;ATP核苷酸类别;ATP自由能载体驱动反应'),
P('细胞工厂总体相似，小分子来源却不同：光合植物借光能用较简单营养物生成有机分子，动物和一些细菌从现存或曾存在的生物获取预成有机物。共同化学基础不意味着营养需求与能量来源相同。','光合生成与异养获取；动物及一些细菌的对象范围，共性与代谢差异。',refs(65),'光合植物简单营养形成有机物;动物部分细菌获取预成有机物;共同基础与营养方式差异')],kind='代谢比较')
gap(E(64),'ATP被同时称为DNA和RNA直接构件的化学精确性','本段概括未区别核糖与脱氧核糖核苷酸，需详细核酸合成章节核对，不把ATP直接等同DNA单体。')
N('膜为什么既需要脂质屏障又需要跨膜运输蛋白？DNA信息如何联系细胞的化学、形态和行为？',[
P('质膜保留合成产物、浓集营养并排废，使反应作为协调体系而非散落溶液运行。屏障不能完全不透，细胞还需嵌入膜的特异运输蛋白输入原料与输出废物；部分运输蛋白家族在远缘类群间仍保守。','保持完整和浓集；不完全封闭、特异进出和部分家族保守。',refs(67,72),'质膜保留产物浓集营养排废;膜维持协调化学系统;特异运输蛋白允许原料和废物交换;部分运输蛋白远缘保守'),
P('运输蛋白决定进入分子，胞内酶决定这些分子的后续反应。DNA通过规定RNA和蛋白的种类与表达，组织细胞化学并影响形态和行为，构成遗传信息—功能分子—整体细胞的连接。','运输选输入、酶选反应；DNA到RNA蛋白到化学形态行为的因果链。',refs(73),'运输蛋白选择输入;胞内酶选择反应;DNA表达连接化学形态行为')],kind='信息功能整合')
N('图1-6中磷脂在油水界面和全水环境为何形成不同结构？两亲性怎样支持膜的自组装？（需看图：头尾朝向、单层与闭合双层）',[
P('两亲性（amphiphilic）分子有亲水头和疏水烃链尾。油水界面可排成单层，头向水、尾向油；在全水环境，形状合适的磷脂把尾隐藏在两层之间，头分别朝外水和内腔水，形成双层并闭合为囊泡。不是任何两亲分子都必然形成同一种双层。','亲水头疏水烃链；界面单层与水中双层两种朝向；形状条件和囊泡闭合。',refs(68,69,70),'两亲性亲水头疏水尾;油水界面单层朝向;全水双层内外亲水;形状条件与闭合囊泡'),
P('分子化学性质促使有序聚集，说明自组装可把细胞合成的组分组织成所需结构。主膜脂疏水部分主要为烃链，但双层例子不能抹去中文古菌四醚单层膜的具体差异。','化学性质→自组装；烃链共同基础与古菌单层差异。',refs(71)+' 2.82','脂质化学性质驱动自组装;烃链共同基础与不同膜型')],images=[('ENFIG0017','front','Figure 1-6，油在上、水在下；囊泡内腔也是水环境。')],kind='膜形成机制')
N('细胞内随机热运动怎样影响扩散和反应？它与ATP驱动的定向运动有什么不同？',[
P('微米尺度下水分子与其他分子随机碰撞，使组分持续热运动，即布朗运动（Brownian motion）。Robert Brown于1827年在水中花粉材料观察到这类运动。随机运动推动扩散并影响反应物碰撞频率，因此静态显微图不代表细胞组分静止。','微米尺度碰撞、布朗运动、1827年观察；扩散、碰撞反应和静态图限制。',refs(75),'微米尺度随机热碰撞;布朗运动名称及1827年观察;热运动推动扩散和反应碰撞;显微图静态不代表组分静止'),
P('许多定向过程使用ATP水解，如离子泵送、胞内大组分运输和细胞移动；微观运动还须克服强黏滞阻力，驱动力解除后定向移动迅速停止，继续受随机热运动扰动，而不会如宏观物体那样持续惯性滑行。','ATP驱动过程范围；黏滞阻力、驱动力停止和热扰动；不持续滑行。',refs(75,77),'ATP驱动多类运动运输;微米环境黏滞阻力;驱动力解除停止定向而继续热扰动')],kind='物理机制')
N('图1-7布朗棘轮怎样把随机膜波动转成前缘定向突出？是否每次突出都必须直接由马达牵拉？（需看图：三个时点膜间隙与肌动蛋白添加）',[
P('膜随机向前波动，暂时拉开与肌动蛋白丝的空隙；合适单体迅速加入丝端，延长的丝阻止膜退回原位。反复的波动、填隙和防回退，使随机运动偏向前突出，构成布朗棘轮（Brownian ratchet），参与动物细胞爬行。','膜前移产生空隙→聚合加单体→阻止回退→净前突完整因果，限定动物爬行例子。',refs(76,78,85),'随机膜波动产生间隙;肌动蛋白单体聚合填隙;延长丝阻回退;布朗棘轮实现净前突'),
P('该步骤的直接机制是聚合捕获随机波动，不是马达蛋白每次都牵拉膜。不能把“不直接由马达驱动此步”扩展成整个细胞爬行或维持系统完全无需能量。','本步骤聚合与马达牵拉区别；局部机制不能外推整过程。',refs(76,85),'前突局部步骤不是直接马达牵拉;局部机制与整个爬行任务的范围区别')],images=[('ENFIG0019','front','Figure 1-7，黑箭头为随机波动／单体加入的过程，灰箭头为净前突。')],kind='运动读图')
N('英文教材的生殖支原体最小基因组例子有多少基因和碱基对？为何不能把其数量直接当作所有自由生活细胞的最少要求？',[
P('生殖支原体（Mycoplasma genitalium）在哺乳动物中寄生，环境预先提供许多所需小分子，但它仍需合成DNA、RNA和蛋白。第7版举525个基因、580070 bp，多数基因在其条件下必需；约500个基因的标题是数量级概括，不能抹去寄生、营养环境及具体物种。','物种、寄生营养条件；仍须合成大分子；525、580070和多数必需的限定。',refs(80),'生殖支原体哺乳动物寄生条件;环境供应预成小分子;仍需合成DNA RNA蛋白;525基因580070bp;约500标题与条件性'),
P('中文第5版用基因删除研究概括约400个基因，英文第7版描述具体物种525个基因，研究对象、条件与统计范围不同。两者都用于讨论细胞复杂性的下界，不构成一个脱离环境的普遍最少数。','约400与525的研究范围区别；不能建立统一普遍门槛。','2.21 '+refs(80),'中文约400删除研究与英文525具体物种不同;最少细胞要求依赖研究和环境条件')],kind='教材数据比较')
N('图1-8的生殖支原体如何体现“基因虽少，基础生命装置仍占显著份额”？请读出图注的基因功能数及图尺。（需看图：电镜截面与0.2μm标尺）',[
P('图为生殖支原体的电镜截面，标尺0.2 μm；电镜使用电子而非光，常规条件下分辨能力高于常规光镜。525基因中43编码tRNA、rRNA等非蛋白RNA，482编码蛋白；其中154参与复制转录翻译等信息过程，98参与膜与表面结构，46参与跨膜运输，71参与能量转换及小分子合成降解。','样本、电子成像、0.2μm；43／482与154／98／46／71的类别对应。',refs(86,87,88),'生殖支原体电镜截面0.2μm;电镜电子成像与常规光镜分辨对比;43非蛋白RNA基因;482蛋白编码基因;154信息过程基因;98膜表面基因;46运输基因;71能量小分子代谢基因')],images=[('ENFIG0018','front','Figure 1-8，0.2μm标尺的文字在原图之外，依原图注补充于此说明。')],kind='图像与数据')
N('基于教材推导：怎样把580070个DNA碱基对换算为约145018字节的理想序列信息？这个换算省略了什么？',[
P('每个位点有4种核苷酸，理想无压缩编码需要log₂4=2 bit。580070位点×2=1160140 bit，除以8 bit/byte得145017.5 byte，约145018 byte。双链互补，记住一条链即可确定另一条，故不把两条链再重复计一遍。','四种状态→2bit；乘位点、除8、单位及舍入；互补链不重复计数。',refs(30,32,80),'四碱基理想编码2bit;580070×2再除8的计算;145018字节近似;互补链不重复计算'),
P('此前提只计算理想核苷酸序列信息，未含文件头、基因注释、压缩、存储格式、染色质状态或细胞其余组分；与一章文字相当是教材类比，不表示一章书能完全重建细胞。','理想序列编码前提与未计信息；类比不等于完整细胞信息。',refs(19,80),'理想序列计算不含格式注释等信息;基因组信息不等于完整细胞全部状态')],basis='基于教材推导',kind='计算推导')
N('从营养输入到复制分裂，怎样整合膜、核酸、蛋白催化与能量解释细胞自复制？',[
P('膜边界保持组成和选择性进出，营养提供构件与能量。DNA保存信息并以互补模板复制，转录产生RNA，mRNA经核糖体指导蛋白合成。蛋白提供反应催化和运输等功能，RNA还可直接发挥作用；自由能持续驱动有序合成，使装置和信息共同复制并随分裂传递。','膜进出与保留、构件能量、DNA复制、RNA转录翻译、催化运输反馈及分裂遗传完整主线。',refs(82,51,67,73),'膜与营养选择性输入;能量构件与有序合成;DNA复制转录RNA;翻译催化与运输反馈;装置信息共同复制分配'),
P('共享基础化学、遗传语言和信息执行方式支持共同祖先，同时不同的组成与调控产生形态、功能和生态差异。统一性不意味着所有细胞的每项速率、调控或营养要求相同。','共同基础与祖先证据；多样性及不绝对同一的限定。',refs(6,35,65,82),'统一化学信息基础与共同祖先;速率调控营养差异与细胞多样性')],kind='整合论述')
N('英文导读为何提醒细胞研究不要只关注可见的动植物？基因组比较、模式生物和病毒研究各有什么用途？',[
P('动植物只是生命多样性的一小部分，许多微小生物肉眼不可见。DNA序列比较能够量化亲缘并构建三域生命树；模式生物有助于集中研究基本分子机制。病毒是极丰富的生物实体，SARS-CoV-2等威胁促使研究集中；“最丰富的实体”与“最多的独立细胞生物”不是同一分类。','可见偏差、序列亲缘、模式生物机制及病毒实体分类；SARS-CoV-2例子。',refs(13,14),'动植物是生命多样性一部分;DNA比较量化三域亲缘;模式生物研究分子机制;病毒实体丰度与细胞生物不同;SARSCoV2研究例子')],kind='研究对象')
N('DNA测序为何改变了对全球生命多样性的认识？微生物的生境与过去的观察偏差是什么？',[
P('生命不仅见于陆地、海洋和光照温带，也有深海、火山热泥、南极冰下及地下数公里生境。很多微生物体小、难获取或难培养，过去较易注意致病或腐木者，并受大型陆生动物视角影响；快速DNA测序等分子分析减少这种偏差。','四类极端生境、微小难采难培养、致病腐木注意偏差及测序改进。',refs(90),'深海热泥南极冰下地下生境;微生物体小难获取难培养;疾病腐木与大型陆生视角偏差;快速测序改变多样性认识'),
P('DNA为通用比较语言，可据序列描述、分类和比较生物并定位生命树亲缘。过去生物活动还直接或间接形成富氧大气、煤石油、铁矿及白垩石灰岩大理岩等地质结果，说明生命既适应环境也长期塑造环境。','序列比较→描述分类亲缘；大气能源矿物地质结果及生命塑造环境。',refs(84,89,91),'通用DNA序列支持描述分类亲缘;生命活动形成富氧大气煤石油;生物活动与铁矿碳酸盐地质结果;生命长期塑造环境')],kind='证据与环境')
